content.css:
.cover { position: relative; width: 780px; height: 585px; overflow: hidden; background: #f5f5f5; }
.cover__bg { position: absolute; inset: 0; background: linear-gradient(135deg, #f8f8f8 0%, #e8e8e8 100%); }
.cover__content { position: relative; display: flex; flex-direction: column; align-items: center; justify-content: center; height: 100%; z-index: 1; }
.cover__title { font-size: 56px; font-weight: 800; color: #1a1a1a; margin: 0 0 16px; letter-spacing: -1px; }
.cover__subtitle { font-size: 24px; font-weight: 400; color: #666; margin: 0; }
.cover__watermark { position: absolute; left: 50%; top: 50%; transform: translate(-50%, -50%); padding: 8px 16px; border-radius: 6px; font-size: 14px; font-weight: 600; color: #fff; background: rgba(0,0,0,0.45); letter-spacing: 0.1em; }
